package com.coworkhub.security;
import jakarta.servlet.http.HttpServletRequest;import jakarta.servlet.http.HttpServletResponse;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.*;
@Component public class JwtFilter extends OncePerRequestFilter {private final JwtService jwt;public JwtFilter(JwtService jwt){this.jwt=jwt;}@Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,jakarta.servlet.FilterChain chain)throws IOException,jakarta.servlet.ServletException{String h=request.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){try{var claims=jwt.parse(h.substring(7));String role=claims.get("role",String.class);var auth=new UsernamePasswordAuthenticationToken(claims.getSubject(),null,List.of(new SimpleGrantedAuthority("ROLE_"+role)));auth.setDetails(claims);SecurityContextHolder.getContext().setAuthentication(auth);}catch(Exception ex){response.setStatus(401);response.setContentType("application/json");response.getWriter().write("{\"error\":\"Token inválido o vencido\",\"codigo\":\"UNAUTHORIZED\",\"timestamp\":\""+java.time.Instant.now()+"\"}");return;}}chain.doFilter(request,response);}}
